  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 10, 'g10_st1', 10, 4, 'category', 'Phân loại đúng nhóm', 'Chọn dụng cụ và thao tác phù hợp để quan sát tế bào dưới kính hiển vi.', '{"categories":["Dụng cụ làm tiêu bản","Không phải dụng cụ làm tiêu bản"],"items":["Lam kính","Lamen","Ống nhỏ giọt","Thước dây đo sân"],"hint":"“Lam kính” thuộc nhóm “Dụng cụ làm tiêu bản”."}'::jsonb, '{"value":[{"name":"Lam kính","catIndex":0},{"name":"Lamen","catIndex":0},{"name":"Ống nhỏ giọt","catIndex":0},{"name":"Thước dây đo sân","catIndex":1}],"explanation":"Lam kính thuộc nhóm Dụng cụ làm tiêu bản; Lamen thuộc nhóm Dụng cụ làm tiêu bản; Ống nhỏ giọt thuộc nhóm Dụng cụ làm tiêu bản; Thước dây đo sân thuộc nhóm Không phải dụng cụ làm tiêu bản."}'::jsonb, '[{"source":"SGK Sinh học 10 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 9. Thực hành: Quan sát tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 10, 'g10_st1', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Chọn dụng cụ và thao tác phù hợp để quan sát tế bào dưới kính hiển vi.', '{"textWithBlanks":"Khi đổi sang vật kính lớn, cần chỉnh [blank] cẩn thận để ảnh rõ.","bankWords":["nét","nhiệt độ nước","âm lượng"],"hint":"Từ cần chọn gồm 1 tiếng và bắt đầu bằng chữ “n”."}'::jsonb, '{"value":"nét","explanation":"Từ đúng là “nét”."}'::jsonb, '[{"source":"SGK Sinh học 10 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 9. Thực hành: Quan sát tế bào"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
$station_release$;
commit;
